<?php

namespace App\Services;

use Ramsey\Uuid\Uuid;

class MobJsonService
{
    public function encode(mixed $data): string
    {
        return json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    }

    public function behaviorManifest(string $name): array
    {
        return [
            'format_version' => 2,
            'header' => [
                'name'              => $name . ' Behavior Pack',
                'description'       => 'Generated by Minecraft Mob Generator',
                'uuid'              => Uuid::uuid4()->toString(),
                'version'           => [1, 0, 0],
                'min_engine_version'=> [1, 21, 0],
            ],
            'modules' => [[
                'type'        => 'data',
                'uuid'        => Uuid::uuid4()->toString(),
                'version'     => [1, 0, 0],
            ]],
        ];
    }

    public function resourceManifest(string $name): array
    {
        return [
            'format_version' => 2,
            'header' => [
                'name'              => $name . ' Resource Pack',
                'description'       => 'Generated by Minecraft Mob Generator',
                'uuid'              => Uuid::uuid4()->toString(),
                'version'           => [1, 0, 0],
                'min_engine_version'=> [1, 21, 0],
            ],
            'modules' => [[
                'type'    => 'resources',
                'uuid'    => Uuid::uuid4()->toString(),
                'version' => [1, 0, 0],
            ]],
        ];
    }

    public function entityBehavior(
        string $identifier,
        int    $health,
        float  $speed,
        string $behaviorType,
        ?int   $attackDamage,
        bool   $isSpawnable,
        bool   $isSummonable,
        float  $collisionWidth,
        float  $collisionHeight
    ): array {
        $components = [
            'minecraft:health'        => ['value' => $health, 'max' => $health],
            'minecraft:movement'      => ['value' => $speed],
            'minecraft:physics'       => (object)[],
            'minecraft:jump.basic'    => (object)[],
            'minecraft:navigation.walk' => ['can_path_over_water' => true],
            'minecraft:collision_box' => ['width' => $collisionWidth, 'height' => $collisionHeight],
            'minecraft:behavior.random_stroll'    => ['priority' => 7, 'speed_multiplier' => 1.0],
            'minecraft:behavior.look_at_player'   => ['priority' => 8, 'look_distance' => 8.0],
            'minecraft:behavior.random_look_around' => ['priority' => 9],
        ];

        if ($behaviorType === 'hostile' || $behaviorType === 'neutral') {
            $damage = $attackDamage ?? 3;
            $components['minecraft:attack'] = ['damage' => $damage];
            $components['minecraft:behavior.melee_attack'] = ['priority' => 3, 'speed_multiplier' => 1.0];
            $components['minecraft:behavior.hurt_by_target'] = ['priority' => 1];
        }

        if ($behaviorType === 'hostile') {
            $components['minecraft:behavior.nearest_attackable_target'] = [
                'priority'    => 2,
                'entity_types'=> [['filters' => ['test' => 'is_family', 'subject' => 'other', 'value' => 'player'], 'max_dist' => 16]],
            ];
        }

        return [
            'format_version' => '1.21.0',
            'minecraft:entity' => [
                'description' => [
                    'identifier'    => 'custom:' . $identifier,
                    'is_spawnable'  => $isSpawnable,
                    'is_summonable' => $isSummonable,
                    'is_experimental' => false,
                ],
                'component_groups' => (object)[],
                'components'       => $components,
                'events'           => (object)[],
            ],
        ];
    }

    public function clientEntity(string $identifier, string $modelType, string $primaryColor, string $secondaryColor): array
    {
        return [
            'format_version' => '1.10.0',
            'minecraft:client_entity' => [
                'description' => [
                    'identifier'        => 'custom:' . $identifier,
                    'materials'         => ['default' => 'entity_alphatest'],
                    'textures'          => ['default' => 'textures/entity/' . $identifier],
                    'geometry'          => ['default' => 'geometry.' . $identifier],
                    'render_controllers'=> ['controller.render.' . $identifier],
                    'spawn_egg'         => [
                        'base_color'    => $primaryColor,
                        'overlay_color' => $secondaryColor,
                    ],
                ],
            ],
        ];
    }

    public function renderController(string $identifier): array
    {
        return [
            'format_version' => '1.8.0',
            'render_controllers' => [
                'controller.render.' . $identifier => [
                    'geometry'  => 'Geometry.default',
                    'materials' => [['*' => 'Material.default']],
                    'textures'  => ['Texture.default'],
                ],
            ],
        ];
    }

    public function geometryJson(string $identifier, string $modelType): array
    {
        $bones = match ($modelType) {
            'quadruped' => $this->quadrupedBones(),
            'creeper'   => $this->creeperBones(),
            default     => $this->humanoidBones(),
        };

        [$tw, $th, $bw, $bh, $offset] = match ($modelType) {
            'quadruped' => [64, 32, 2.0, 2.0,   [0, 0.75, 0]],
            'creeper'   => [64, 32, 1.5, 1.5,   [0, 0.75, 0]],
            default     => [64, 64, 2.0, 2.5,   [0, 1.0,  0]],
        };

        return [
            'format_version' => '1.12.0',
            'minecraft:geometry' => [[
                'description' => [
                    'identifier'           => 'geometry.' . $identifier,
                    'texture_width'        => $tw,
                    'texture_height'       => $th,
                    'visible_bounds_width' => $bw,
                    'visible_bounds_height'=> $bh,
                    'visible_bounds_offset'=> $offset,
                ],
                'bones' => $bones,
            ]],
        ];
    }

