            ],
            [
                'name' => 'legFrontRight', 'parent' => 'body', 'pivot' => [-3, 6, -5],
                'cubes' => [['origin' => [-5, 0, -7], 'size' => [4, 6, 4], 'uv' => [16, 0]]],
            ],
            [
                'name' => 'legFrontLeft', 'parent' => 'body', 'pivot' => [3, 6, -5],
