                'cubes' => [['origin' => [-4, 6, -2], 'size' => [8, 12, 4], 'uv' => [16, 16]]],
            ],
            [
                'name' => 'head', 'parent' => 'body', 'pivot' => [0, 18, 0],
                'cubes' => [['origin' => [-4, 18, -4], 'size' => [8, 8, 8], 'uv' => [0, 0]]],
            ],
            [
                'name' => 'leg0', 'parent' => 'root', 'pivot' => [-2, 6, -2],
